using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Configuration ---
var openAiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException("Set the OPENAI_API_KEY environment variable.");
var searchApiKey = Environment.GetEnvironmentVariable("SEARCH_API_KEY") ?? "";
var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o";

// --- Build the AI client with tool support ---
IChatClient client = new OpenAIClient(openAiKey)
    .GetChatClient(model)
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

// --- Tools ---
var notes = new NoteStore();

var tools = new List<AITool>
{
    AIFunctionFactory.Create(
        ([Description("The search query")] string query) => WebSearchTool.SearchAsync(query, searchApiKey),
        "web_search",
        "Searches the web for information on a given query and returns relevant snippets."),
    AIFunctionFactory.Create(
        ([Description("Title for the note")] string title, [Description("Content of the note")] string content) =>
        {
            notes.Add(title, content);
            return $"Note saved: {title}";
        },
        "take_note",
        "Saves a note with a title and content for later reference in the summary."),
    AIFunctionFactory.Create(
        () => notes.GetAll(),
        "get_notes",
        "Retrieves all notes taken so far.")
};

// --- Prompt ---
var topic = args.Length > 0 ? string.Join(' ', args) : "recent advances in quantum computing 2026";

Console.WriteLine($"🔍 Research Agent Starting...");
Console.WriteLine($"📋 Topic: {topic}");
Console.WriteLine(new string('─', 60));

var messages = new List<ChatMessage>
{
    new(ChatRole.System, """
        You are a research agent. Your goal is to research the given topic thoroughly.

        Follow this workflow:
        1. Search the web for information on the topic (make 2-3 searches with different angles).
        2. Take notes on the key findings from each search.
        3. After gathering enough information, retrieve your notes and produce a comprehensive summary.

        Always use your tools. Provide a final summary with key points and sources.
        """),
    new(ChatRole.User, $"Please research the following topic and provide a summary: {topic}")
};

var options = new ChatOptions { Tools = tools };

// --- Agent loop ---
var response = await client.GetResponseAsync(messages, options);

Console.WriteLine();
Console.WriteLine(new string('─', 60));
Console.WriteLine("📝 RESEARCH SUMMARY");
Console.WriteLine(new string('─', 60));
Console.WriteLine(response.Text);
Console.WriteLine(new string('─', 60));

if (notes.Count > 0)
{
    Console.WriteLine($"\n📌 {notes.Count} note(s) were taken during research.");
}

// --- Tool Implementations ---

public static class WebSearchTool
{
    private static readonly HttpClient Http = new();

    public static async Task<string> SearchAsync(string query, string apiKey)
    {
        Console.WriteLine($"  🌐 Searching: \"{query}\"");

        // Use a real search API if key is provided, otherwise return simulated results
        if (!string.IsNullOrEmpty(apiKey))
        {
            try
            {
                var encoded = Uri.EscapeDataString(query);
                var url = $"https://api.bing.microsoft.com/v7.0/search?q={encoded}&count=5";
                var request = new HttpRequestMessage(HttpMethod.Get, url);
                request.Headers.Add("Ocp-Apim-Subscription-Key", apiKey);

                var response = await Http.SendAsync(request);
                if (response.IsSuccessStatusCode)
                {
                    var json = await response.Content.ReadFromJsonAsync<JsonElement>();
                    var results = new List<string>();
                    if (json.TryGetProperty("webPages", out var webPages) &&
                        webPages.TryGetProperty("value", out var values))
                    {
                        foreach (var item in values.EnumerateArray().Take(5))
                        {
                            var name = item.GetProperty("name").GetString();
                            var snippet = item.GetProperty("snippet").GetString();
                            var itemUrl = item.GetProperty("url").GetString();
                            results.Add($"- {name}\n  {snippet}\n  Source: {itemUrl}");
                        }
                    }
                    return results.Count > 0
                        ? string.Join("\n\n", results)
                        : "No results found.";
                }
            }
            catch (Exception ex)
            {
                return $"Search error: {ex.Message}. Returning no results.";
            }
        }

        // Fallback: inform the model that search is unavailable
        return $"[Search API unavailable] No live results for: \"{query}\". " +
               "Please synthesize your response from your training knowledge and note that live sources were not available.";
    }
}

public class NoteStore
{
    private readonly List<(string Title, string Content)> _notes = [];

    public int Count => _notes.Count;

    public void Add(string title, string content)
    {
        _notes.Add((title, content));
        Console.WriteLine($"  📝 Note taken: \"{title}\"");
    }

    public string GetAll()
    {
        if (_notes.Count == 0) return "No notes taken yet.";

        return string.Join("\n\n", _notes.Select((n, i) =>
            $"[Note {i + 1}] {n.Title}\n{n.Content}"));
    }
}

